 34→	Binary() string
 35→	EntireAgent() string
 36→	PromptPattern() string
 37→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
 38→	// Slower agents (e.g. Gemini) return values > 1.
 39→	TimeoutMultiplier() float64
 40→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
 41→	StartSession(ctx context.Context, dir string) (Session, error)
 42→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
 43→	// Called before any tests run. Implementations should be idempotent.
 44→	Bootstrap() error
 45→	// IsTransientError returns true if the error from RunPrompt looks like
 46→	// a transient API failure (e.g. 500, rate limit, network error) that
 47→	// is worth retrying.
 48→	IsTransientError(out Output, err error) bool
 49→}
 50→
 51→type Session interface {
 52→	Send(input string) error
 53→	WaitFor(pattern string, timeout time.Duration) (string, error)
 54→	Capture() string
 55→	Close() error
 56→}
