 58→var registry []Agent
 59→var gates = map[string]chan struct{}{}
 60→
 61→func Register(a Agent) {
 62→	registry = append(registry, a)
 63→}
 64→
 65→// RegisterGate sets a concurrency limit for an agent's tests.
 66→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
 67→// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
 68→func RegisterGate(name string, defaultMax int) {
 69→	max := defaultMax
 70→	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
 71→		max = v
 72→	}
 73→	gates[name] = make(chan struct{}, max)
 74→}
 75→
 76→// AcquireSlot blocks until a test slot is available for the agent or the
 77→// context is cancelled. Returns a non-nil error if the context expires
 78→// before a slot opens.
 79→func AcquireSlot(ctx context.Context, a Agent) error {
 80→	g, ok := gates[a.Name()]
 81→	if !ok {
 82→		return nil
 83→	}
 84→	select {
 85→	case g <- struct{}{}:
 86→		return nil
 87→	case <-ctx.Done():
 88→		return ctx.Err()
 89→	}
 90→}
