120→func (g *Gemini) StartSession(ctx context.Context, dir string) (Session, error) {
121→	name := fmt.Sprintf("gemini-test-%d", time.Now().UnixNano())
122→	// Unset CI and GITHUB_ACTIONS so gemini doesn't force headless mode —
123→	// it checks both in isHeadlessMode() and skips interactive TUI entirely.
124→	s, err := NewTmuxSession(name, dir, []string{"CI", "GITHUB_ACTIONS"}, "env", "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0", g.Binary(), "--model", geminiDefaultModel, "-y")
125→	if err != nil {
126→		return nil, err
127→	}
128→
129→	// Dismiss startup dialogs (auth, workspace trust, etc.)
130→	for range 10 {
131→		content, err := s.WaitFor(`(Type your message|trust|Enter to select|Enter to confirm)`, 30*time.Second)
132→		if err != nil {
133→			_ = s.Close()
134→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
135→		}
136→		if strings.Contains(content, "Type your message") {
137→			break
138→		}
139→		_ = s.SendKeys("Enter")
140→		time.Sleep(500 * time.Millisecond)
141→	}
142→	s.stableAtSend = ""
