const versionPkg = "github.com/entireio/cli/cmd/entire/cli/versioninfo"

// versionLdflags returns ldflags that inject the git version and commit into
// the built binary. Falls back to "dev" / "unknown" if git is unavailable.
func versionLdflags(moduleRoot string) string {
	version := gitOutput(moduleRoot, "describe", "--tags", "--always", "--dirty")
	if version == "" {
		version = "dev"
	}
	commit := gitOutput(moduleRoot, "rev-parse", "--short", "HEAD")
	if commit == "" {
		commit = "unknown"
	}
	return "-X " + versionPkg + ".Version=" + version +
		" -X " + versionPkg + ".Commit=" + commit
}

func gitOutput(dir string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

