package versioninfo

import "runtime/debug"

// Version and Commit are set at build time via ldflags.
// When not set (plain `go build`), init() populates them from
// Go's embedded VCS info (git revision + modified flag).
var (
	Version = "dev"
	Commit  = "unknown"
)

func init() {
	if Version != "dev" {
		return
	}
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return
	}
	var revision, modified string
	for _, s := range info.Settings {
		switch s.Key {
		case "vcs.revision":
			revision = s.Value
		case "vcs.modified":
			modified = s.Value
		}
	}
	if revision == "" {
		return
	}
	short := revision
	if len(short) > 7 {
		short = short[:7]
	}
	Commit = short
	Version = "dev-" + short
	if modified == "true" {
		Version += "-dirty"
	}
}

