184→// Git runs a git command in the repo and logs it to ConsoleLog.
185→func (s *RepoState) Git(t *testing.T, args ...string) {
186→	t.Helper()
187→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
188→	Git(t, s.Dir, args...)
