191→// StartSession starts an interactive session and registers it for pane
192→// capture in artifacts. Returns nil if the agent does not support interactive
193→// mode. The session is closed automatically during test cleanup.
194→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
195→	t.Helper()
196→	session, err := s.Agent.StartSession(ctx, s.Dir)
197→	if err != nil {
