391→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
392→// the initial commit. Returns the bare repo path.
393→func SetupBareRemote(t *testing.T, s *RepoState) string {
394→	t.Helper()
395→
396→	var bareDir string
397→	if os.Getenv("E2E_KEEP_REPOS") != "" {
398→		var err error
399→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
400→		if err != nil {
401→			t.Fatalf("create bare remote dir: %v", err)
402→		}
403→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
404→	} else {
405→		bareDir = t.TempDir()
406→	}
407→
408→	Git(t, bareDir, "init", "--bare")
409→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
410→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
411→	return bareDir
412→}
